// =====================================================================
// salvar-foto-original-storage — sobe a foto original pro bucket do
// Supabase Storage assim que ela chega, antes de perguntar o nome do
// produto. Motivo: entre a foto chegar e o vendedor responder o nome do
// produto pode passar bem mais que alguns minutos (é uma pausa esperando
// resposta humana) — a URL temporária da Meta não sobrevive até lá, mas
// uma URL do Storage sim.
//
// Segredos (SUPABASE_URL, SUPABASE_STORAGE_BUCKET, SUPABASE_SERVICE_ROLE_KEY)
// vêm das variáveis de ambiente do container ($env), definidas no .env do
// Docker — Code node não anexa Credential pela UI. Ver
// docs/gemini-supabase-storage-setup.md.

const SUPABASE_URL = $env.SUPABASE_URL;
const BUCKET = $env.SUPABASE_STORAGE_BUCKET || 'listing-photos';

const listingId = $('criar-listing').first().json.id;
const item = $input.first();
const foto = item.binary.data;
const extensao = (foto.mimeType || 'image/jpeg').includes('png') ? 'png' : 'jpg';
const caminho = `${listingId}/original.${extensao}`;

await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${caminho}`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Content-Type': foto.mimeType,
    'x-upsert': 'true'
  },
  body: Buffer.from(foto.data, 'base64')
});

return [{
  json: {
    listing_id: listingId,
    original_photo_storage_url: `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${caminho}`
  }
}];

