const GARANTIA_ENVIO = 'GARANTIA E ENVIO\nProduto verificado antes da postagem. Envio rápido com embalagem protegida.\nEm caso de dúvidas, entre em contato pelo canal de mensagens do anúncio para atendimento ágil.';

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
}

const titulo = (parsed.titulo || 'Produto à venda').slice(0, 60);
const descricaoBase = parsed.descricao || 'Não foi possível gerar a descrição automaticamente — edite manualmente.';
const descricao = `${descricaoBase}\n\n${GARANTIA_ENVIO}`;

return [{ json: { titulo, descricao } }];

let row;
try {
  // caminho: geração nova (título/descrição acabaram de ser gerados/salvos)
  row = $('atualizar-listing-titulo-descricao').first().json;
} catch (e) {
  // caminho: botão "gerar de novo" — lê o que já existe na listing
  row = $('buscar-listing-para-regeneracao').first().json;
}

const cc = $('buscar-vendedor').first().json.conversation_context;
const contexto = typeof cc === 'string' ? JSON.parse(cc || '{}') : (cc || {});

return [{
  json: {
    listing_id: row.id,
    generated_title: row.generated_title,
    generated_description: row.generated_description,
    original_photo_storage_url: row.original_photo_url,
    nome_produto: contexto.nome_produto
  }
}];

// =====================================================================
// gerar-prompts-gpt — manda o esqueleto das 8 cenas + o anúncio já
// gerado (título/descrição) pro GPT, pede de volta um prompt customizado
