    regras_fixas: 'Imagem quadrada de referência de tamanho do produto. SE E SOMENTE SE a descrição do produto fornecida abaixo contiver uma medida/dimensão real confirmada, mostrar um diagrama com linhas de medida e ESSE NÚMERO REAL escrito ON-IMAGE. SE NÃO houver medida real confirmada na descrição, NÃO INVENTAR NENHUM NÚMERO — em vez disso, gerar uma \'referência de escala visual\': o produto posicionado ao lado de um objeto cotidiano comum e reconhecível (ex: uma mão humana, um celular, uma moeda — escolha o que for proporcionalmente coerente com o tamanho provável da categoria do produto), sem nenhum número impresso, só a comparação visual de tamanho. Fundo neutro, iluminação de estúdio. Texto em português correto (se houver). Quadrado 1:1.'
  }
];
const MODEL = 'gemini-3.1-flash-image';

const promptsPorNome = $('gerar-prompts-gpt').first().json.prompts;
const fotoOrigem = $('baixar-foto-para-gerar').first().binary.data;
const fotoBase64 = fotoOrigem.data;
const mimeTypeOrigem = fotoOrigem.mimeType || 'image/jpeg';

async function chamarGemini(promptCompleto, imageConfig) {
  return this.helpers.httpRequest({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent`,
    headers: {
      'x-goog-api-key': $env.GEMINI_API_KEY,
      'Content-Type': 'application/json'
    },
    body: {
      contents: [{
        parts: [
          { text: promptCompleto },
          { inline_data: { mime_type: mimeTypeOrigem, data: fotoBase64 } }
        ]
      }],
      generationConfig: {
        responseModalities: ['IMAGE'],
        imageConfig
      }
    },
    json: true
  });
}

async function gerarCena(esqueleto) {
  const promptFinal = promptsPorNome[esqueleto.nome];
  if (!promptFinal) {
    throw new Error(`GPT não devolveu prompt para a cena "${esqueleto.nome}"`);
  }

  const promptCompleto = `Usando a imagem de referência do produto anexada, gere uma nova foto do MESMO produto exato (preserve rigorosamente cor, formato, proporções, rótulos e texturas reais do objeto — não invente detalhes que o produto não tem). ${promptFinal}`;

  let resposta;
  try {
    resposta = await chamarGemini.call(this, promptCompleto, { aspectRatio: '1:1', imageSize: '2K' });
  } catch (e) {
    // image_size "2K" pode não ser aceito — tenta de novo sem ele (fica em 1K).
    resposta = await chamarGemini.call(this, promptCompleto, { aspectRatio: '1:1' });
  }

  const partes = resposta?.candidates?.[0]?.content?.parts ?? [];
  const parteImagem = partes.find(p => p.inlineData || p.inline_data);
  const inline = parteImagem?.inlineData ?? parteImagem?.inline_data;

  if (!inline) {
    throw new Error(`Gemini não retornou imagem para a cena "${esqueleto.nome}": ${JSON.stringify(resposta).slice(0, 500)}`);
  }

  return {
    json: { scene: esqueleto.nome, is_cover: !!esqueleto.is_cover },
    binary: {
      imagem: {
        data: inline.data,
        mimeType: inline.mimeType ?? inline.mime_type ?? 'image/png',
        fileName: `${esqueleto.nome}.png`
      }
    }
  };
}

return Promise.all(ESQUELETOS_CENAS.map(esqueleto => gerarCena.call(this, esqueleto)));

const SUPABASE_URL = $env.SUPABASE_URL;
const BUCKET = $env.SUPABASE_STORAGE_BUCKET || 'listing-photos';

const listingId = $('preparar-para-imagens').first().json.listing_id;
const geradas = $input.all(); // 8 items de gerar-8-fotos-customizadas

async function subir(caminho, binario) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${caminho}`,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Type': binario.mimeType,
      'x-upsert': 'true'
    },
    body: Buffer.from(binario.data, 'base64')
  });
  return `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${caminho}`;
}

const generatedPhotos = await Promise.all(
  geradas.map(async (item) => {
    const caminho = `${listingId}/${item.json.scene}.png`;
    const url = await subir.call(this, caminho, item.binary.imagem);
    return { url, scene: item.json.scene, is_cover: item.json.is_cover };
  })
);

return [{ json: { listing_id: listingId, generated_photos: generatedPhotos } }];

